  const TAARRUZ = "<i>26 Ağustos 1922 sabahı Türk ordusu, Afyonkarahisar yakınlarında Büyük Taarruz'u başlattı. Başkomutan Mustafa Kemal Paşa, saldırıyı Kocatepe'den izledi. 30 Ağustos'ta Dumlupınar çevresinde yapılan Başkomutanlık Meydan Muharebesi kazanıldı. Türk ordusu 9 Eylül 1922'de İzmir'e girdi.</i>";
